/**
 * 保存menu.xml文件
 *
 * @param menuXml
 */
public void saveMenuXml(VersionInfoXml menuXml) throws IOException, DocumentException {
    XMLOptionUtil.writeXml(menuXml, item -> {
        Element menusEls = menuXml.getRootElement();
        List<Map<String, Object>> componentVersionInfoResult = menuXml.getComponentVersionInfoResult();
        String dbName = menuXml.getDbName();
        Properties properties = menuXml.getProperties();
        String metaDirectioryPath = menuXml.getMetaInfoPath();

        //查询组件菜单信息
        String sql = "SELECT * FROM " + dbName + ".component_menu WHERE r_component_version_info = " + componentVersionInfoResult.get(0).get("id")
                + " AND r_component_menu IS NULL ORDER BY i_sort";
        List<Map<String, Object>> componentMenuInfoList = null;
        try {
            componentMenuInfoList = commonDAO.get(sql);
        } catch (Exception e) {
            e.printStackTrace();
            throw HidoErrorCode.SQL_ERROR.exception("查询菜单数据库异常");
        }
        log.info("【sql】：" + sql);
        log.info("【size】：" + componentMenuInfoList.size());
        log.info("【componentMenuInfoList】：" + componentMenuInfoList);
        if (CollectionUtils.isNotEmpty(componentMenuInfoList)) {
            //菜单编号与父菜单Element元素的关联表
            Map<String, Element> CODE_ELS_MAP = new HashMap<String, Element>();
            //创建堆栈对象
            Stack<Map<String, Object>> stack = new Stack<Map<String, Object>>();
            //把第一层节点放入堆栈
            for (Map<String, Object> menu : componentMenuInfoList) {
                stack.push(menu);
                CODE_ELS_MAP.put(String.valueOf(menu.get("c_menu_code")), menusEls.addElement("menu"));
            }

            Map<String, Object> menu = null;
            Element menuEls = null;
            while (stack.size() > 0) {
                //从堆栈获取元素
                menu = stack.pop();
                menuEls = CODE_ELS_MAP.get(String.valueOf(menu.get("c_menu_code")));
                //设置属性
                menuEls.addAttribute("code", String.valueOf(menu.get("c_menu_code")));
                menuEls.addAttribute("type", String.valueOf(menu.get("c_menu_type")));
                if (menu.get("r_component_segment") != null) {
                    sql = "SELECT * FROM " + dbName + ".component_segment WHERE id = " + menu.get("r_component_segment");
                    List<Map<String, Object>> csList = null;
                    try {
                        csList = commonDAO.get(sql);
                    } catch (Exception e) {
                        e.printStackTrace();
                        throw HidoErrorCode.SQL_ERROR.exception("查询程序段异常");
                    }
                    log.info("     【sql】：" + sql);
                    log.info("     【size】：" + csList.size());
                    log.info("     【csList】：" + csList);
                    if (CollectionUtils.isNotEmpty(csList)) {
                        menuEls.addAttribute("refId", String.valueOf(csList.get(0).get("c_segment_id")));
                    }
                }
                if (menu.get("c_url") != null && Strings.isNotBlank(menu.get("c_url").toString())) {
                    menuEls.addAttribute("url", String.valueOf(menu.get("c_url")));
                }
                menuEls.addAttribute("sort", String.valueOf(menu.get("i_sort")));
                //可能有" "问题
                if (menu.get("c_open_type") != null && Strings.isNotBlank(menu.get("c_open_type").toString().trim())) {
                    menuEls.addAttribute("openType", String.valueOf(menu.get("c_open_type")));
                }
                properties.setProperty("menu." + menu.get("c_menu_code") + ".displayName", menu.get("c_display_name") != null ? String.valueOf(menu.get("c_display_name")) : "");
                properties.setProperty("menu." + menu.get("c_menu_code") + ".description", menu.get("c_description") != null ? String.valueOf(menu.get("c_description")) : "");
                //保存文件
                if (menu.get("o_icon") != null) {
                    byte[] iconBytes = (byte[]) menu.get("o_icon");
                    String iconType = IconUtil.iconType(iconBytes);
                    FileUtil.byte2File(iconBytes, metaDirectioryPath + "icon" + File.separator + "menu", menu.get("c_menu_code") + "." + iconType);
                }

                //查询是否有子节点
                sql = "SELECT * FROM " + dbName + ".component_menu WHERE r_component_version_info = " + componentVersionInfoResult.get(0).get("id")
                        + " AND r_component_menu  = " + menu.get("id") + " ORDER BY i_sort";
                List<Map<String, Object>> childMenusList = null;
                try {
                    childMenusList = commonDAO.get(sql);
                } catch (Exception e) {
                    e.printStackTrace();
                    throw HidoErrorCode.SQL_ERROR.exception("查询菜单数据库异常");
                }
                log.info("     【sql】：" + sql);
                log.info("     【size】：" + childMenusList.size());
                log.info("     【childMenusList】：" + childMenusList);
                if (CollectionUtils.isNotEmpty(childMenusList)) {
                    for (Map<String, Object> childMenu : childMenusList) {
                        stack.push(childMenu);
                        CODE_ELS_MAP.put(String.valueOf(childMenu.get("c_menu_code")), menuEls.addElement("menu"));
                    }
                }
            }
        }
    });
}

/**
 * 循环插入菜单项
 *
 * @param rootMenus
 * @param properties
 * @param rComponentVersionInfo
 * @param metaPath
 * @throws Exception
 */
private void loopInsertMenuItem(Element rootMenus, Properties properties, int rComponentVersionInfo,
                                String metaPath) throws Exception {
    // 菜单编号与父菜单物理ID的关联表
    Map<String, Integer> CODE_ID_MAP = new HashMap<String, Integer>();
    // 创建堆栈对象
    Stack<Element> stack = new Stack<Element>();
    // 如果菜单元素为空，则直接返回
    if (rootMenus == null || rootMenus.elements().isEmpty()) {
        return;
    }
    // 把第一层节点放入堆栈
    for (Element els : (List<Element>) rootMenus.elements()) {
        stack.push(els);
        // 第一层菜单没有父菜单ID
        CODE_ID_MAP.put(els.attributeValue("code"), null);
    }

    Element menu = null;
    while (stack.size() > 0) {
        // 从堆栈获取元素
        menu = stack.pop();
        // 插入数据库
        // 待保存的数据
        List<Map<String, Object>> data = new ArrayList<Map<String, Object>>();
        Map<String, Object> dataMap = new HashMap<String, Object>();
        data.add(dataMap);

        // 获取refId-段标识
        String segmentId = menu.attributeValue("refId");
        Integer componentSegmentId = null;
        if (StringUtils.isNotBlank(segmentId)) {
            List<Map<String, Object>> result = commonDAO
                    .get("SELECT id FROM model_controlled_db.component_segment WHERE r_component_version_info = "
                            + rComponentVersionInfo + " AND c_segment_id = \"" + segmentId + "\"");
            if (CollectionUtils.isNotEmpty(result)) {
                Object id = result.get(0).get("id");
                if (id != null) {
                    componentSegmentId = (Integer) id;
                }
            }
        }

        dataMap.put("r_component_version_info", rComponentVersionInfo);
        dataMap.put("r_component_segment", componentSegmentId);
        dataMap.put("r_component_menu", CODE_ID_MAP.get(menu.attributeValue("code")));
        dataMap.put("c_menu_code", ComponentModelUtil.getNullString(menu.attributeValue("code")));
        dataMap.put("c_display_name", ComponentModelUtil
                .getNullString(properties.getProperty("menu." + menu.attributeValue("code") + ".displayName")));
        dataMap.put("c_description", ComponentModelUtil
                .getNullString(properties.getProperty("menu." + menu.attributeValue("code") + ".description")));
        //图片存在svg和png两种情况
        String iconPath = this.svgPngIcon(metaPath + "icon" + File.separator + "menu" + File.separator + menu.attributeValue("code"));
        if (Strings.isNotBlank(iconPath)) {
            dataMap.put("o_icon",
                    FileUtil.file2Byte(new File(iconPath)));
        }
        dataMap.put("c_menu_type", ComponentModelUtil.getNullString(menu.attributeValue("type")));
        dataMap.put("c_url", ComponentModelUtil.getNullString(menu.attributeValue("url")));
        dataMap.put("i_sort", ComponentModelUtil.getNullString(menu.attributeValue("sort")));
        dataMap.put("c_open_type", ComponentModelUtil.getNullString(menu.attributeValue("openType")));
        // 保存数据
        List<Map<String, Object>> result = commonDAO.insert("model_controlled_db.component_menu",
                JSONObject.toJSONString(data));
        if (dataMap.get("o_icon") != null) {
            // 更新o_icon字段
            result.get(0).put("o_icon", dataMap.get("o_icon"));
            commonDAO.updateFileColumn("model_controlled_db.component_menu", result.get(0));
        }

        if (!menu.elements().isEmpty()) {
            for (Element els : (List<Element>) menu.elements()) {
                stack.push(els);
                CODE_ID_MAP.put(els.attributeValue("code"), (Integer) result.get(0).get("id"));
            }
        }
    }
}
